  })

  it('slices head and tail over the cap and expands on click', () => {
    const view = render(<ReadBlock label="a" lines={lines(10)} totalLines={10} maxLines={4} />)
    // maxLines 4: head = ceil(4/2) = 2, tail = 4 - 2 = 2, 6 hidden.
